function walk(dir, depth = 0, maxDepth = 3) {
  const out = [];
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return out; }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      out.push({ type: 'dir', path: full, depth });
      if (depth < maxDepth) out.push(...walk(full, depth + 1, maxDepth));
    } else {
      out.push({ type: 'file', path: full, depth, size: fs.statSync(full).size });
    }
  }
  return out;
}

